public class Main {
    static class BankAccount {
        private double balance;
        void deposit(double amount) {
            if (amount <= 0) throw new IllegalArgumentException("Amount must be positive");
            balance += amount;
        }
        double balance() { return balance; }
    }

    public static void main(String[] args) {
        var acc = new BankAccount();
        acc.deposit(250);
        System.out.println("Balance: " + acc.balance());
        try { acc.deposit(-5); }
        catch (IllegalArgumentException e) { System.out.println("Rejected: " + e.getMessage()); }
    }
}

// Output:
// Balance: 250.0
// Rejected: Amount must be positive

import java.util.List;

public class Main {
    interface Account { double monthlyFee(); }
    record Savings() implements Account { public double monthlyFee() { return 0; } }
    record Current() implements Account { public double monthlyFee() { return 4.5; } }

    public static void main(String[] args) {
        for (Account a : List.of(new Savings(), new Current()))
            System.out.println(a.getClass().getSimpleName() + ": " + a.monthlyFee());
    }
}

// Output:
// Savings: 0.0
// Current: 4.5

